const j = $json;

const wh = $('Receive file (Webhook)').first();

const fromOcr = ('ParsedResults' in j) || ('IsErroredOnProcessing' in j) || ('error' in j);

let text = '';

let ocrFailed = false;

if (fromOcr) {

  if (Array.isArray(j.ParsedResults)) {

    text = j.ParsedResults.map(p => p.ParsedText || '').join('\n');

  }

  ocrFailed = !!j.IsErroredOnProcessing || !!j.error || !Array.isArray(j.ParsedResults);

} else {

  text = j.text || '';

}

// Arabic-Indic / Persian digits and separators -> ASCII (critical for amounts and dates)

const mapDigit = (c) => {

  const code = c.charCodeAt(0);

  if (code >= 0x0660 && code <= 0x0669) return String(code - 0x0660);

  if (code >= 0x06F0 && code <= 0x06F9) return String(code - 0x06F0);

  if (code === 0x066B) return '.';

  if (code === 0x066C) return ',';

  return c;

};

text = text

  .replace(/[\u0660-\u0669\u06F0-\u06F9\u066B\u066C]/g, mapDigit)

  .replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F]/g, '')

  .replace(/\r/g, '')

  .replace(/[ \t]+/g, ' ')

  .replace(/\n{3,}/g, '\n\n')

  .trim();

return { json: {

  request_id: String($execution.id),

  filename: (wh.binary && wh.binary.file && wh.binary.file.fileName) || 'unknown',

  extraction_method: fromOcr ? 'ocr' : 'text-layer',

  ocr_failed: ocrFailed,

  raw_text: text,

  text_length: text.length

}};

