// ---- tunable thresholds ----

const HIGH_AMOUNT = 50000;     // currency units; above this -> always human review

const MIN_CONFIDENCE = 0.8;    // LLM self-reported confidence (weak signal, see notes)

const MAX_AGE_DAYS = 400;

const MIN_TEXT_LEN = 100;

const ai = $json.output || {};

const meta = $('Normalize & clean text').first().json;

const flags = [];

const missing = (v) => v === null || v === undefined || v === '';

// 1. Required fields

for (const f of ['supplier_name', 'invoice_number', 'invoice_date', 'total']) {

  if (missing(ai[f])) flags.push('missing:' + f);

}

// 2. Dates

const now = new Date();

if (!missing(ai.invoice_date)) {

  const d = new Date(ai.invoice_date);

  if (isNaN(d.getTime())) flags.push('invalid_date');

  else {

    if (d > now) flags.push('future_date');

    if ((now - d) / 864e5 > MAX_AGE_DAYS) flags.push('stale_date');

  }

}

if (!missing(ai.due_date) && !missing(ai.invoice_date) &&

    new Date(ai.due_date) < new Date(ai.invoice_date)) flags.push('due_before_invoice');

// 3. Amounts and arithmetic reconciliation

if (typeof ai.total !== 'number' || ai.total <= 0) flags.push('non_positive_total');

if (typeof ai.total === 'number' && ai.total > HIGH_AMOUNT) flags.push('high_amount');

if (typeof ai.subtotal === 'number' && typeof ai.tax === 'number' && typeof ai.total === 'number' &&

    Math.abs(ai.subtotal + ai.tax - ai.total) > 0.02) flags.push('total_mismatch');

if (Array.isArray(ai.line_items) && ai.line_items.length && typeof ai.subtotal === 'number') {

  const sum = ai.line_items.reduce((s, i) => s + (Number(i.amount) || 0), 0);

  if (Math.abs(sum - ai.subtotal) > 0.05) flags.push('line_items_mismatch');

}

// 4. Grounding: extracted values must literally appear in the source text (anti-hallucination)

const flat = (meta.raw_text || '').replace(/[,\s]/g, '');

if (!missing(ai.invoice_number) &&

    !flat.includes(String(ai.invoice_number).replace(/[,\s]/g, ''))) flags.push('invoice_number_not_in_text');

if (typeof ai.total === 'number' &&

    !flat.includes(String(ai.total)) && !flat.includes(ai.total.toFixed(2))) flags.push('total_not_in_text');

// 5. Source quality and confidence

if (meta.ocr_failed) flags.push('ocr_failed');

if (meta.text_length < MIN_TEXT_LEN) flags.push('very_little_text');

if (typeof ai.confidence === 'number' && ai.confidence < MIN_CONFIDENCE) flags.push('low_confidence');

if (Array.isArray(ai.uncertain_fields) && ai.uncertain_fields.length) flags.push('model_uncertain');

// 6. Duplicates (demo only: static data persists in ACTIVE runs, not manual tests.

//    In production use a DB unique constraint on supplier + invoice_number.)

const sd = $getWorkflowStaticData('global');

sd.seen = sd.seen || {};

const key = String(ai.supplier_name || '').toLowerCase().trim() + '|' + String(ai.invoice_number || '').trim();

if (!missing(ai.invoice_number)) {

  if (sd.seen[key]) flags.push('possible_duplicate');

  else sd.seen[key] = new Date().toISOString();

}

return { json: {

  request_id: meta.request_id,

  filename: meta.filename,

  extraction_method: meta.extraction_method,

  supplier_name: ai.supplier_name ?? null,

  invoice_number: ai.invoice_number ?? null,

  invoice_date: ai.invoice_date ?? null,

  due_date: ai.due_date ?? null,

  currency: ai.currency ?? null,

  subtotal: ai.subtotal ?? null,

  tax: ai.tax ?? null,

  total: ai.total ?? null,

  line_items_json: JSON.stringify(ai.line_items || []),

  ai_confidence: ai.confidence ?? null,

  flags: flags.join(', '),

  flag_count: flags.length,

  needs_review: flags.length > 0,

  status: flags.length > 0 ? 'pending_review' : 'auto_approved',

  processed_at: new Date().toISOString()

}};

const base = $('Validate & score').first().json;

const input = $input.first().json;

const response = input.data || input;

const decision = response.Decision || null;

const comment = response['Reviewer comment'] || '';

let status = base.status;

if (decision === 'Approve') {
  status = 'approved_by_human';
}

if (decision === 'Reject') {
  status = 'rejected_by_human';
}

return {
  json: {
    ...base,
    reviewer_decision: decision || 
      (base.needs_review ? 'pending' : 'n/a (auto)'),
    reviewer_comment: comment,
    status
  }
};
